INSERT IGNORE INTO topic_content (topic_id, summary_np, summary_en, characteristics, effects, classical_reference, sanskrit_term, sanskrit_meaning) VALUES
(90,'प्रतिपदा शुक्ल पक्षको १ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ० डिग्री देखि १२ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता अग्नि हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Pratipada (S Paksha) is the 1st tithi of the shukla paksha. It runs while the Sun–Moon elongation is 0° to 12°, and its traditional deity is Agni.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि १ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता अग्नि मानिएकाले अग्निदेवको उपासनाले शुद्धि र नयाँ आरम्भका काममा सहयोग मानिन्छ।','नयाँ काम सुरु गर्ने, देवालय जाने र व्रत आरम्भ गर्ने जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','प्रतिपदा','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(91,'द्वितीया शुक्ल पक्षको २ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १२ डिग्री देखि २४ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता ब्रह्मा हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Dwitiya (S Paksha) is the 2nd tithi of the shukla paksha. It runs while the Sun–Moon elongation is 12° to 24°, and its traditional deity is Brahma.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि २ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता ब्रह्मा मानिएकाले ब्रह्मादेवसँग सृजना र शुभ संकल्पका काम जोडिन्छन्।','अध्ययन-अध्यापन, स्नान-दान र शुभ संकल्पका काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','द्वितीया','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(92,'तृतीया शुक्ल पक्षको ३ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २४ डिग्री देखि ३६ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता गौरी हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Tritiya (S Paksha) is the 3rd tithi of the shukla paksha. It runs while the Sun–Moon elongation is 24° to 36°, and its traditional deity is Gauri.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ३ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता गौरी मानिएकाले गौरी (पार्वती) सँग विवाह र सुख-सौभाग्यका काम जोडिन्छन्।','गौरी-गणेश पूजा र विवाह सम्बन्धी शुभ कार्य जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','तृतीया','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(93,'चतुर्थी शुक्ल पक्षको ४ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ३६ डिग्री देखि ४८ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता गणेश हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Chaturthi (S Paksha) is the 4th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 36° to 48°, and its traditional deity is Ganesha.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ४ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता गणेश मानिएकाले गणपतिको पूजाले विघ्न र बाधा हटाउने मानिन्छ।','गणेश पूजा र संकट निवारणका व्रत जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्। शुक्ल चतुर्थीमा संकष्टी चतुर्थीको व्रत मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','चतुर्थी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(94,'पञ्चमी शुक्ल पक्षको ५ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ४८ डिग्री देखि ६० डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता नाग हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Panchami (S Paksha) is the 5th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 48° to 60°, and its traditional deity is the Nagas.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ५ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता नाग मानिएकाले नागदेवतासँग नागपूजा र सर्पदोष निवारणका काम जोडिन्छन्।','नाग पूजा, विद्याआरम्भ र लेखन-कलाका काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','पञ्चमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(95,'षष्ठी शुक्ल पक्षको ६ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ६० डिग्री देखि ७२ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता कार्तिकेय हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Shashthi (S Paksha) is the 6th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 60° to 72°, and its traditional deity is Kartikeya.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ६ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता कार्तिकेय मानिएकाले स्कन्द (कार्तिकेय) सँग सन्तान, शौर्य र रक्षाका काम जोडिन्छन्।','स्कन्द (कार्तिकेय) पूजा र सन्तानसम्बन्धी काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','षष्ठी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(96,'सप्तमी शुक्ल पक्षको ७ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ७२ डिग्री देखि ८४ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता सूर्य हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Saptami (S Paksha) is the 7th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 72° to 84°, and its traditional deity is the Sun.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ७ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता सूर्य मानिएकाले सूर्यदेवसँग स्वास्थ्य, प्रतिष्ठा र उज्यालोका काम जोडिन्छन्।','सूर्य उपासना र स्वास्थ्य-प्रतिष्ठाका शुभ काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','सप्तमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(97,'अष्टमी शुक्ल पक्षको ८ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ८४ डिग्री देखि ९६ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता दुर्गा हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Ashtami (S Paksha) is the 8th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 84° to 96°, and its traditional deity is Durga.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ८ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता दुर्गा मानिएकाले दुर्गा-कालीको उपासना र उपवासका काम यसै तिथिमा पर्छन्।','दुर्गा-काली पूजा र उपवास जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्। अष्टमीमा दुर्गा-कालीको उपवास वा पूजा गर्ने चलन छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','अष्टमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(98,'नवमी शुक्ल पक्षको ९ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ९६ डिग्री देखि १०८ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता दुर्गा हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Navami (S Paksha) is the 9th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 96° to 108°, and its traditional deity is Durga.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ९ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता दुर्गा मानिएकाले दुर्गा (भैरवी) को शक्तिसाधना र विजयका काम यसै तिथिमा शुभ मानिन्छन्।','दुर्गा पूजा र विजय-प्रतिष्ठाका काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','नवमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(99,'दशमी शुक्ल पक्षको १० औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १०८ डिग्री देखि १२० डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता यम हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Dashami (S Paksha) is the 10th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 108° to 120°, and its traditional deity is Yama.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि १० औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता यम मानिएकाले यमसँग दण्ड र पितृसम्बन्धी मान्यता जोडिए पनि विजय र प्रतिष्ठाका काम शुभ मानिन्छन्।','विजय र प्रतिष्ठाका काम, सरकारी वा कानूनी काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','दशमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(100,'एकादशी शुक्ल पक्षको ११ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १२० डिग्री देखि १३२ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता विष्णु हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Ekadashi (S Paksha) is the 11th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 120° to 132°, and its traditional deity is Vishnu.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि ११ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता विष्णु मानिएकाले विष्णुसँग एकादशी व्रतको परम्परा जोडिएको छ।','विष्णु व्रत, उपवास र दान जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्। शुक्ल एकादशी विष्णु व्रत र उपवासका लागि सबैभन्दा प्रसिद्ध तिथि हो।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','एकादशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(101,'द्वादशी शुक्ल पक्षको १२ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १३२ डिग्री देखि १४४ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता विष्णु हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Dwadashi (S Paksha) is the 12th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 132° to 144°, and its traditional deity is Vishnu.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि १२ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता विष्णु मानिएकाले विष्णुसँग पारिवारिक धर्म र व्रतका काम जोडिन्छन्।','विष्णु पूजा र पारिवारिक धार्मिक काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','द्वादशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(102,'त्रयोदशी शुक्ल पक्षको १३ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १४४ डिग्री देखि १५६ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता शिव हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Trayodashi (S Paksha) is the 13th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 144° to 156°, and its traditional deity is Shiva.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि १३ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता शिव मानिएकाले शिवसँग प्रदोष व्रत र शिवपूजाका काम जोडिन्छन्।','शिव-गणेश पूजा र प्रदोष व्रत जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्। त्रयोदशीमा प्रदोष व्रत हुन्छ, जुन शिवपूजाका लागि शुभ मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','त्रयोदशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(103,'चतुर्दशी शुक्ल पक्षको १४ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १५६ डिग्री देखि १६८ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता शिव हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Chaturdashi (S Paksha) is the 14th tithi of the shukla paksha. It runs while the Sun–Moon elongation is 156° to 168°, and its traditional deity is Shiva.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि १४ औं तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता शिव मानिएकाले शिवसँग शिवरात्रिको व्रत जोडिएको छ।','देवी-शिव पूजा र व्रत जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','चतुर्दशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(104,'पूर्णिमा शुक्ल पक्षको अन्तिम तिथि र पूरा चन्द्र देखिने दिन हो। सूर्य र चन्द्रबीचको दूरी १६८ डिग्री देखि १८० डिग्री सम्म पुगेका बेला यो तिथि चल्छ। मान्यता अनुसार यसकी देवता चन्द्र हुन्।','Purnima is the full-moon day and the last tithi of the shukla paksha. It runs when the Sun–Moon elongation is 168° to 180°, and its deity is the Moon.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि शुक्ल पक्षको अन्तिम तिथि हो, जुन शुक्ल पक्षमा चन्द्र बढ्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई आरम्भ र वृद्धिका कामको पक्ष मानिन्छ। देवता चन्द्र मानिएकाले चन्द्रदेवसँग पूर्णिमाको पूजा, दान र उत्सवका काम जोडिन्छन्।','चन्द्र पूजा, दान र उत्सव जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। शुक्ल पक्षमा चन्द्र बढ्दो भएकाले नयाँ आरम्भ, वृद्धि र समृद्धिका काम बढी उपयुक्त हुन्छन्। पूर्णिमामा चन्द्र पूजा, दान र उत्सव हुन्छ — गुरु पूर्णिमा, कुमार पूर्णिमा जस्ता पर्व यसै दिन पर्छन्। यो तिथि शुभ कार्य र धार्मिक आयोजनका लागि उपयुक्त मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','पूर्णिमा','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(105,'प्रतिपदा कृष्ण पक्षको १ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १८० डिग्री देखि १९२ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता अग्नि हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Pratipada (K Paksha) is the 1st tithi of the krishna paksha. It runs while the Sun–Moon elongation is 180° to 192°, and its traditional deity is Agni.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको १ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता अग्नि मानिएकाले अग्निदेवको उपासनाले शुद्धि र नयाँ आरम्भका काममा सहयोग मानिन्छ।','नयाँ काम सुरु गर्ने, देवालय जाने र व्रत आरम्भ गर्ने जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','प्रतिपदा','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(106,'द्वितीया कृष्ण पक्षको २ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी १९२ डिग्री देखि २०४ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता ब्रह्मा हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Dwitiya (K Paksha) is the 2nd tithi of the krishna paksha. It runs while the Sun–Moon elongation is 192° to 204°, and its traditional deity is Brahma.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको २ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता ब्रह्मा मानिएकाले ब्रह्मादेवसँग सृजना र शुभ संकल्पका काम जोडिन्छन्।','अध्ययन-अध्यापन, स्नान-दान र शुभ संकल्पका काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','द्वितीया','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(107,'तृतीया कृष्ण पक्षको ३ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २०४ डिग्री देखि २१६ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता गौरी हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Tritiya (K Paksha) is the 3rd tithi of the krishna paksha. It runs while the Sun–Moon elongation is 204° to 216°, and its traditional deity is Gauri.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ३ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता गौरी मानिएकाले गौरी (पार्वती) सँग विवाह र सुख-सौभाग्यका काम जोडिन्छन्।','गौरी-गणेश पूजा र विवाह सम्बन्धी शुभ कार्य जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','तृतीया','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(108,'चतुर्थी कृष्ण पक्षको ४ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २१६ डिग्री देखि २२८ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता गणेश हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Chaturthi (K Paksha) is the 4th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 216° to 228°, and its traditional deity is Ganesha.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ४ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता गणेश मानिएकाले गणपतिको पूजाले विघ्न र बाधा हटाउने मानिन्छ।','गणेश पूजा र संकट निवारणका व्रत जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्। कृष्ण चतुर्थी पनि संकष्टी चतुर्थीको व्रतका लागि मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','चतुर्थी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(109,'पञ्चमी कृष्ण पक्षको ५ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २२८ डिग्री देखि २४० डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता नाग हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Panchami (K Paksha) is the 5th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 228° to 240°, and its traditional deity is the Nagas.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ५ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता नाग मानिएकाले नागदेवतासँग नागपूजा र सर्पदोष निवारणका काम जोडिन्छन्।','नाग पूजा, विद्याआरम्भ र लेखन-कलाका काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','पञ्चमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(110,'षष्ठी कृष्ण पक्षको ६ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २४० डिग्री देखि २५२ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता कार्तिकेय हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Shashthi (K Paksha) is the 6th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 240° to 252°, and its traditional deity is Kartikeya.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ६ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता कार्तिकेय मानिएकाले स्कन्द (कार्तिकेय) सँग सन्तान, शौर्य र रक्षाका काम जोडिन्छन्।','स्कन्द (कार्तिकेय) पूजा र सन्तानसम्बन्धी काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','षष्ठी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(111,'सप्तमी कृष्ण पक्षको ७ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २५२ डिग्री देखि २६४ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता सूर्य हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Saptami (K Paksha) is the 7th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 252° to 264°, and its traditional deity is the Sun.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ७ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता सूर्य मानिएकाले सूर्यदेवसँग स्वास्थ्य, प्रतिष्ठा र उज्यालोका काम जोडिन्छन्।','सूर्य उपासना र स्वास्थ्य-प्रतिष्ठाका शुभ काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','सप्तमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(112,'अष्टमी कृष्ण पक्षको ८ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २६४ डिग्री देखि २७६ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता दुर्गा हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Ashtami (K Paksha) is the 8th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 264° to 276°, and its traditional deity is Durga.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ८ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता दुर्गा मानिएकाले दुर्गा-कालीको उपासना र उपवासका काम यसै तिथिमा पर्छन्।','दुर्गा-काली पूजा र उपवास जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्। कृष्ण अष्टमी (कालाष्टमी) मा उपवासको विशेष महत्त्व मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','अष्टमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(113,'नवमी कृष्ण पक्षको ९ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २७६ डिग्री देखि २८८ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता दुर्गा हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Navami (K Paksha) is the 9th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 276° to 288°, and its traditional deity is Durga.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ९ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता दुर्गा मानिएकाले दुर्गा (भैरवी) को शक्तिसाधना र विजयका काम यसै तिथिमा शुभ मानिन्छन्।','दुर्गा पूजा र विजय-प्रतिष्ठाका काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','नवमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(114,'दशमी कृष्ण पक्षको १० औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी २८८ डिग्री देखि ३०० डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता यम हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Dashami (K Paksha) is the 10th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 288° to 300°, and its traditional deity is Yama.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको १० औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता यम मानिएकाले यमसँग दण्ड र पितृसम्बन्धी मान्यता जोडिए पनि विजय र प्रतिष्ठाका काम शुभ मानिन्छन्।','विजय र प्रतिष्ठाका काम, सरकारी वा कानूनी काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','दशमी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(115,'एकादशी कृष्ण पक्षको ११ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ३०० डिग्री देखि ३१२ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता विष्णु हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Ekadashi (K Paksha) is the 11th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 300° to 312°, and its traditional deity is Vishnu.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको ११ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता विष्णु मानिएकाले विष्णुसँग एकादशी व्रतको परम्परा जोडिएको छ।','विष्णु व्रत, उपवास र दान जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्। कृष्ण एकादशी पनि व्रत र दानका लागि उत्तिकै शुभ मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','एकादशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(116,'द्वादशी कृष्ण पक्षको १२ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ३१२ डिग्री देखि ३२४ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता विष्णु हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Dwadashi (K Paksha) is the 12th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 312° to 324°, and its traditional deity is Vishnu.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको १२ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता विष्णु मानिएकाले विष्णुसँग पारिवारिक धर्म र व्रतका काम जोडिन्छन्।','विष्णु पूजा र पारिवारिक धार्मिक काम जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','द्वादशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(117,'त्रयोदशी कृष्ण पक्षको १३ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ३२४ डिग्री देखि ३३६ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता शिव हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Trayodashi (K Paksha) is the 13th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 324° to 336°, and its traditional deity is Shiva.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको १३ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता शिव मानिएकाले शिवसँग प्रदोष व्रत र शिवपूजाका काम जोडिन्छन्।','शिव-गणेश पूजा र प्रदोष व्रत जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्। कृष्ण त्रयोदशी पनि प्रदोष व्रत र शिवपूजाका लागि शुभ हो।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','त्रयोदशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(118,'चतुर्दशी कृष्ण पक्षको १४ औं तिथि हो। सूर्य र चन्द्रबीचको कोणीय दूरी ३३६ डिग्री देखि ३४८ डिग्री को बीच भएको बेला यो तिथि चल्छ। मान्यता अनुसार यस तिथिकी देवता शिव हुन् (ग्रन्थ र परम्पराअनुसार देवताको विवरण फरक-फरक हुन सक्छ)।','Chaturdashi (K Paksha) is the 14th tithi of the krishna paksha. It runs while the Sun–Moon elongation is 336° to 348°, and its traditional deity is Shiva.','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको १४ औं तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता शिव मानिएकाले शिवसँग शिवरात्रिको व्रत जोडिएको छ।','देवी-शिव पूजा र व्रत जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्। यही कृष्ण चतुर्दशीमा महाशिवरात्रिको व्रत पर्छ, जसलाई वर्षको सबैभन्दा ठूलो शिव व्रत मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','चतुर्दशी','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(119,'अमावस्या कृष्ण पक्षको अन्तिम तिथि र अँध्यारो चन्द्र (नयाँ चन्द्र) को दिन हो। सूर्य र चन्द्रबीचको दूरी ३४८ डिग्री देखि ३६० डिग्री सम्म पुगेका बेला यो तिथि चल्छ। मान्यता अनुसार यसकी देवता पितृ हुन्।','Amavasya is the new-moon day and the last tithi of the krishna paksha. It runs when the Sun–Moon elongation is 348° to 360°, and its deities are the pitrus (ancestors).','तिथि भनेको सूर्य र चन्द्रबीचको कोणीय दूरीको १२ डिग्री भएको खण्ड हो — चन्द्रले सूर्यबाट यति दूरी बढेपछि एउटा तिथि पूरा हुन्छ। यसरी एक चन्द्र मासमा ३० तिथि र दुई पक्षमा १५-१५ तिथि हुन्छन्। तिथिको अवधि १० देखि १२ घडी (लगभग २० देखि २७ घण्टा) सम्म हुन सक्छ, त्यसैले कहिलेकाहीँ एउटै सूर्योदयमा दुई तिथि पुग्छन् वा कुनै तिथि नै नपुग्ने अवस्था (क्षय र अधिक तिथि) बन्छ। यो तिथि कृष्ण पक्षको अन्तिम तिथि हो, जुन कृष्ण पक्षमा चन्द्र घट्दो अवस्थामा हुन्छ, त्यसैले यस पक्षलाई समापन, दान-तर्पण र संयमका कामको पक्ष मानिन्छ। देवता पितृ मानिएकाले पितृसँग तर्पण, श्राद्ध र दानका काम जोडिन्छन्।','पितृ तर्पण, श्राद्ध र दान जस्ता काम यस तिथिमा गर्नु शुभ मानिन्छ। कृष्ण पक्षमा चन्द्र घट्दो भएकाले समापन, दान-तर्पण, उपवास र संयमका काम बढी उपयुक्त हुन्छन्। अमावस्यामा पितृ तर्पण, श्राद्ध र दान गरिन्छ; यसलाई नयाँ काम र मङ्गल कार्यका लागि अशुभ मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग तिथि विचार (सूर्य सिद्धान्त तथा परम्परागत पञ्चाङ्ग)','अमावस्या','सूर्य-चन्द्र दूरीको १२ डिग्रीको खण्ड — चन्द्र मासका ३० मध्ये एक भाग।'),
(120,'आइतबार (रविवार) हप्ताको पहिलो दिन हो र यसको वार-स्वामी सूर्य ग्रह हो। पश्चिमी हप्ताको सुरुवात र हिन्दू परम्परामा सूर्यवारलाई पहिलो वार मानिन्छ।','Sunday is the 1 day of the week in the panchanga and is ruled by Sun. The seven varas follow the seven planets Sun, Moon, Mars, Mercury, Jupiter, Venus and Saturn.','सूर्य आत्मा, पिता, प्रतिष्ठा र ऊर्जाका कारक मानिन्छ। यस दिन सूर्यलाई अर्घ्य दिने, पीलो रङका वस्त्र लगाउने र सूर्य मन्त्र जप गर्ने चलन छ। वारका सातै दिनहरू सूर्य, चन्द्र, मङ्गल, बुध, गुरु, शुक्र र शनि — यी सात ग्रहसँग जोडिएका छन्, जुन सप्ताह चक्रको आधार हो।','यस दिन सूर्य उपासना, दान र नयाँ कामको सुरुवात गर्नु शुभ मानिन्छ। तर केही परम्परामा विवाह र मङ्गलिक कार्य आइतबारमा नगर्ने चलन पनि छ, त्यसैले विवाहका लागि पञ्चाङ्ग हेरेर निर्णय गर्नु उचित हुन्छ।','वैदिक ज्योतिष — सप्ताह र वार-चक्र (वार-स्वामी ग्रह)','आइतबार — सूर्यवार','हप्ताको सात दिन मध्ये एक; प्रत्येक दिन एक-एक ग्रहको स्वामित्वमा।'),
(121,'सोमबार हप्ताको दोस्रो दिन हो र यसको वार-स्वामी चन्द्र ग्रह हो। नेपाल र भारतमा यस दिन शिव र चन्द्र उपासनाको विशेष महत्त्व छ।','Monday is the 2 day of the week in the panchanga and is ruled by Moon. The seven varas follow the seven planets Sun, Moon, Mars, Mercury, Jupiter, Venus and Saturn.','चन्द्र मन, भावना, माता र शान्तिका कारक मानिन्छ। यस दिन शिवलिङ्गमा जल चढाउने, सेतो वस्त्र लगाउने र सोम मन्त्र जप गर्ने चलन छ। तेजस्वी र शान्त मन राख्न र मानसिक सन्तुलन कायम गर्न सोमबारलाई शुभ मानिन्छ।','शिव पूजा, जल दान, रुद्राभिषेक र शान्तिका काम यस दिन शुभ हुन्छन्। मनसम्बन्धी चिन्ता, निद्राको अभाव वा भावनात्मक उथलपुथलको उपचारका लागि पनि यो दिन उपयुक्त मानिन्छ।','वैदिक ज्योतिष — सप्ताह र वार-चक्र (वार-स्वामी ग्रह)','सोमबार — चन्द्रवार','हप्ताको सात दिन मध्ये एक; प्रत्येक दिन एक-एक ग्रहको स्वामित्वमा।'),
(122,'मंगलबार हप्ताको तेस्रो दिन हो र यसको वार-स्वामी मंगल ग्रह हो। मंगल ऊर्जा, शक्ति, भूमि र शस्त्रका कारक मानिन्छ।','Tuesday is the 3 day of the week in the panchanga and is ruled by Mars. The seven varas follow the seven planets Sun, Moon, Mars, Mercury, Jupiter, Venus and Saturn.','यो दिन हनुमान र मंगल उपासनासँग जोडिएको छ — हनुमान मन्दिरमा जाने, लाल रङका वस्त्र लगाउने र मंगल मन्त्र जप गर्ने चलन छ। मंगल दोष (कुण्डलीमा मंगलको कठोर अवस्था) को शान्तिका उपाय यसै दिन गर्ने परम्परा छ।','नेपाली र हिन्दू परम्परामा मंगलबारमा नयाँ काम, विवाह, गृहप्रवेश र व्यापार आरम्भ गर्न टाढा बसिन्छ। तर मंगल दोष शान्ति, हनुमान पूजा र शक्तिसम्बन्धी उपाय यसै दिन शुभ मानिन्छ।','वैदिक ज्योतिष — सप्ताह र वार-चक्र (वार-स्वामी ग्रह)','मंगलबार — मङ्गलवार','हप्ताको सात दिन मध्ये एक; प्रत्येक दिन एक-एक ग्रहको स्वामित्वमा।'),
(123,'बुधबार हप्ताको चौथो दिन हो र यसको वार-स्वामी बुध ग्रह हो। बुध बुद्धि, वाणी, लेखन, व्यापार र परिवहनका कारक मानिन्छ।','Wednesday is the 4 day of the week in the panchanga and is ruled by Mercury. The seven varas follow the seven planets Sun, Moon, Mars, Mercury, Jupiter, Venus and Saturn.','यस दिन गणेश र बुध उपासनासँग जोडिएको छ — गणेशलाई दूर्वा चढाउने, हरियो रङका वस्त्र लगाउने र बुध मन्त्र जप गर्ने चलन छ। विद्यार्थी, लेखक, व्यापारी र कलाकारका लागि यो दिन विशेष शुभ मानिन्छ।','व्यापारमा नयाँ लेनदेन, लेखन, भाषा, गणित, परीक्षा र यात्रासम्बन्धी काम यस दिन शुभ हुन्छन्। बुध दोष वा बुध कमजोर हुने अवस्थामा गणेश पूजा र दान यसै दिन गर्ने परम्परा छ।','वैदिक ज्योतिष — सप्ताह र वार-चक्र (वार-स्वामी ग्रह)','बुधबार — बुधवार','हप्ताको सात दिन मध्ये एक; प्रत्येक दिन एक-एक ग्रहको स्वामित्वमा।'),
(124,'बिहीबार (गुरुवार) हप्ताको पाँचौं दिन हो र यसको वार-स्वामी बृहस्पति (गुरु) ग्रह हो। बृहस्पति ज्ञान, धर्म, सम्पत्ति र सन्तानका कारक मानिन्छ।','Thursday is the 5 day of the week in the panchanga and is ruled by Jupiter. The seven varas follow the seven planets Sun, Moon, Mars, Mercury, Jupiter, Venus and Saturn.','यो दिन विष्णु, बृहस्पति र सरस्वती उपासनासँग जोडिएको छ — पीलो वस्त्र लगाउने, गुरु मन्त्र जप गर्ने, विद्या र दान गर्ने चलन छ। विद्यार्थीका लागि यो सप्ताहको सबैभन्दा शुभ दिन मानिन्छ।','विद्यारम्भ, विवाहका लागि पञ्चाङ्ग हेर्ने, गृहप्रवेश, नयाँ व्यवसाय र धार्मिक कार्य यस दिन अति शुभ मानिन्छन्। गुरु ग्रहको कमजोरी वा गुरु दोषको शान्तिका उपाय पनि बिहीबारमा गर्ने चलन छ।','वैदिक ज्योतिष — सप्ताह र वार-चक्र (वार-स्वामी ग्रह)','बिहीबार — बृहस्पतिवार','हप्ताको सात दिन मध्ये एक; प्रत्येक दिन एक-एक ग्रहको स्वामित्वमा।'),
(125,'शुक्रबार हप्ताको छैटौं दिन हो र यसको वार-स्वामी शुक्र ग्रह हो। शुक्र कला, सौन्दर्य, प्रेम, विवाह र भोग-विलासका कारक मानिन्छ।','Friday is the 6 day of the week in the panchanga and is ruled by Venus. The seven varas follow the seven planets Sun, Moon, Mars, Mercury, Jupiter, Venus and Saturn.','यो दिन लक्ष्मी र शुक्र उपासनासँग जोडिएको छ — सेतो वा गुलाबी वस्त्र लगाउने, शुक्र मन्त्र जप गर्ने र स्त्री-पुरुष दुवैका लागि सौन्दर्य तथा स्वास्थ्यका काम शुभ मानिन्छ। कला, संगीत र साहित्यका काममा यो दिन विशेष अनुकूल छ।','विवाह-सम्बन्धी वार्ता, सगाई, वस्त्र-आभूषण किन्ने, गृह सजाउने र कलात्मक काम यस दिन शुभ हुन्छन्। शुक्र दोष वा वैवाहिक जीवनमा कठिनाइको शान्तिका उपाय पनि शुक्रबारमा गर्ने परम्परा छ।','वैदिक ज्योतिष — सप्ताह र वार-चक्र (वार-स्वामी ग्रह)','शुक्रबार — शुक्रवार','हप्ताको सात दिन मध्ये एक; प्रत्येक दिन एक-एक ग्रहको स्वामित्वमा।'),
(126,'शनिबार हप्ताको सातौं र अन्तिम दिन हो र यसको वार-स्वामी शनि ग्रह हो। शनि कर्म, अनुशासन, धैर्य, दण्ड र मोक्षका कारक मानिन्छ।','Saturday is the 7 day of the week in the panchanga and is ruled by Saturn. The seven varas follow the seven planets Sun, Moon, Mars, Mercury, Jupiter, Venus and Saturn.','यो दिन शनि उपासनासँग जोडिएको छ — कालो वस्त्र लगाउने, तेल लगाउने, शनि मन्त्र जप गर्ने र काले तिलको दान गर्ने चलन छ। शनि न्यायप्रिय ग्रह मानिन्छ, त्यसैले सत्य र परिश्रमका काममा यो दिन अनुकूल हुन्छ।','शनि पूजा, तेल लगाउने, काले तिल वा अन्नको दान र सेवाका काम यस दिन शुभ हुन्छन्। तर नेपाली परम्परामा शनिबारमा नयाँ काम, विवाह र गृहप्रवेश गर्न टाढा बसिन्छ — शनि दोषको शान्तिका उपाय यसै दिन गरिन्छ।','वैदिक ज्योतिष — सप्ताह र वार-चक्र (वार-स्वामी ग्रह)','शनिबार — शनिवार','हप्ताको सात दिन मध्ये एक; प्रत्येक दिन एक-एक ग्रहको स्वामित्वमा।'),
(127,'विष्कम्भ योग नित्य योगमध्ये १ औं योग हो। सूर्य र चन्द्रको जोडलाई ०°००'' – १३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ आसन र स्तम्भ भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Vishkambha Yoga is number 1 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 0°00'' – 13°20''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। विष्कम्भ योगको शाब्दिक अर्थ आसन र स्तम्भ हो। यस योगको डिग्री सीमा ०°००'' – १३°२०'' हो, जुन १ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','विष्कम्भ योग','सूर्य-चन्द्र जोडको ०°००'' – १३°२०'' अंश — शाब्दिक अर्थ: आसन र स्तम्भ।'),
(128,'प्रीति योग नित्य योगमध्ये २ औं योग हो। सूर्य र चन्द्रको जोडलाई १३°२०'' – २६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ स्नेह र प्रेम भन्ने यस योगलाई कम अनुकूल योगको रूपमा चिनिन्छ।','Priti Yoga is number 2 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 13°20'' – 26°40''. Traditional classification: less favourable.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। प्रीति योगको शाब्दिक अर्थ स्नेह र प्रेम हो। यस योगको डिग्री सीमा १३°२०'' – २६°४०'' हो, जुन २ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो कम अनुकूल योग हो र सामान्य काम गर्न मिल्छ, तर अति महत्त्वपूर्ण मङ्गलिक कामका लागि राम्रो योग हेर्नु उचित हुन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','प्रीति योग','सूर्य-चन्द्र जोडको १३°२०'' – २६°४०'' अंश — शाब्दिक अर्थ: स्नेह र प्रेम।'),
(129,'आयुष्मान् योग नित्य योगमध्ये ३ औं योग हो। सूर्य र चन्द्रको जोडलाई २६°४०'' – ४०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ दीर्घायु भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Ayushman Yoga is number 3 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 26°40'' – 40°00''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। आयुष्मान् योगको शाब्दिक अर्थ दीर्घायु हो। यस योगको डिग्री सीमा २६°४०'' – ४०°००'' हो, जुन ३ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','आयुष्मान् योग','सूर्य-चन्द्र जोडको २६°४०'' – ४०°००'' अंश — शाब्दिक अर्थ: दीर्घायु।'),
(130,'सौभाग्य योग नित्य योगमध्ये ४ औं योग हो। सूर्य र चन्द्रको जोडलाई ४०°००'' – ५३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ सौभाग्य भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Saubhagya Yoga is number 4 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 40°00'' – 53°20''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। सौभाग्य योगको शाब्दिक अर्थ सौभाग्य हो। यस योगको डिग्री सीमा ४०°००'' – ५३°२०'' हो, जुन ४ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','सौभाग्य योग','सूर्य-चन्द्र जोडको ४०°००'' – ५३°२०'' अंश — शाब्दिक अर्थ: सौभाग्य।'),
(131,'शोभन योग नित्य योगमध्ये ५ औं योग हो। सूर्य र चन्द्रको जोडलाई ५३°२०'' – ६६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ सुन्दरता र चमक भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Shobhana Yoga is number 5 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 53°20'' – 66°40''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। शोभन योगको शाब्दिक अर्थ सुन्दरता र चमक हो। यस योगको डिग्री सीमा ५३°२०'' – ६६°४०'' हो, जुन ५ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','शोभन योग','सूर्य-चन्द्र जोडको ५३°२०'' – ६६°४०'' अंश — शाब्दिक अर्थ: सुन्दरता र चमक।'),
(132,'अतिगण्ड योग नित्य योगमध्ये ६ औं योग हो। सूर्य र चन्द्रको जोडलाई ६६°४०'' – ८०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ ठूलो बाधा भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Atiganda Yoga is number 6 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 66°40'' – 80°00''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। अतिगण्ड योगको शाब्दिक अर्थ ठूलो बाधा हो। यस योगको डिग्री सीमा ६६°४०'' – ८०°००'' हो, जुन ६ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','अतिगण्ड योग','सूर्य-चन्द्र जोडको ६६°४०'' – ८०°००'' अंश — शाब्दिक अर्थ: ठूलो बाधा।'),
(133,'सुकर्मा योग नित्य योगमध्ये ७ औं योग हो। सूर्य र चन्द्रको जोडलाई ८०°००'' – ९३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ कल्याणकारी कर्म भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Sukarma Yoga is number 7 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 80°00'' – 93°20''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। सुकर्मा योगको शाब्दिक अर्थ कल्याणकारी कर्म हो। यस योगको डिग्री सीमा ८०°००'' – ९३°२०'' हो, जुन ७ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','सुकर्मा योग','सूर्य-चन्द्र जोडको ८०°००'' – ९३°२०'' अंश — शाब्दिक अर्थ: कल्याणकारी कर्म।'),
(134,'धृति योग नित्य योगमध्ये ८ औं योग हो। सूर्य र चन्द्रको जोडलाई ९३°२०'' – १०६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ धैर्य र स्थिरता भन्ने यस योगलाई कम अनुकूल योगको रूपमा चिनिन्छ।','Dhriti Yoga is number 8 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 93°20'' – 106°40''. Traditional classification: less favourable.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। धृति योगको शाब्दिक अर्थ धैर्य र स्थिरता हो। यस योगको डिग्री सीमा ९३°२०'' – १०६°४०'' हो, जुन ८ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो कम अनुकूल योग हो र सामान्य काम गर्न मिल्छ, तर अति महत्त्वपूर्ण मङ्गलिक कामका लागि राम्रो योग हेर्नु उचित हुन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','धृति योग','सूर्य-चन्द्र जोडको ९३°२०'' – १०६°४०'' अंश — शाब्दिक अर्थ: धैर्य र स्थिरता।'),
(135,'शूल योग नित्य योगमध्ये ९ औं योग हो। सूर्य र चन्द्रको जोडलाई १०६°४०'' – १२०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ भाला — संघर्ष भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Shula Yoga is number 9 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 106°40'' – 120°00''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। शूल योगको शाब्दिक अर्थ भाला — संघर्ष हो। यस योगको डिग्री सीमा १०६°४०'' – १२०°००'' हो, जुन ९ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','शूल योग','सूर्य-चन्द्र जोडको १०६°४०'' – १२०°००'' अंश — शाब्दिक अर्थ: भाला — संघर्ष।'),
(136,'गण्ड योग नित्य योगमध्ये १० औं योग हो। सूर्य र चन्द्रको जोडलाई १२०°००'' – १३३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ गाँठो र अवरोध भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Ganda Yoga is number 10 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 120°00'' – 133°20''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। गण्ड योगको शाब्दिक अर्थ गाँठो र अवरोध हो। यस योगको डिग्री सीमा १२०°००'' – १३३°२०'' हो, जुन १० औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','गण्ड योग','सूर्य-चन्द्र जोडको १२०°००'' – १३३°२०'' अंश — शाब्दिक अर्थ: गाँठो र अवरोध।'),
(137,'वृद्धि योग नित्य योगमध्ये ११ औं योग हो। सूर्य र चन्द्रको जोडलाई १३३°२०'' – १४६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ वृद्धि र विस्तार भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Vriddhi Yoga is number 11 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 133°20'' – 146°40''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। वृद्धि योगको शाब्दिक अर्थ वृद्धि र विस्तार हो। यस योगको डिग्री सीमा १३३°२०'' – १४६°४०'' हो, जुन ११ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','वृद्धि योग','सूर्य-चन्द्र जोडको १३३°२०'' – १४६°४०'' अंश — शाब्दिक अर्थ: वृद्धि र विस्तार।'),
(138,'ध्रुवा योग नित्य योगमध्ये १२ औं योग हो। सूर्य र चन्द्रको जोडलाई १४६°४०'' – १६०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ स्थिरता भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Dhruva Yoga is number 12 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 146°40'' – 160°00''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। ध्रुवा योगको शाब्दिक अर्थ स्थिरता हो। यस योगको डिग्री सीमा १४६°४०'' – १६०°००'' हो, जुन १२ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','ध्रुवा योग','सूर्य-चन्द्र जोडको १४६°४०'' – १६०°००'' अंश — शाब्दिक अर्थ: स्थिरता।'),
(139,'व्याघात योग नित्य योगमध्ये १३ औं योग हो। सूर्य र चन्द्रको जोडलाई १६०°००'' – १७३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ प्रहार भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Vyaghata Yoga is number 13 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 160°00'' – 173°20''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। व्याघात योगको शाब्दिक अर्थ प्रहार हो। यस योगको डिग्री सीमा १६०°००'' – १७३°२०'' हो, जुन १३ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','व्याघात योग','सूर्य-चन्द्र जोडको १६०°००'' – १७३°२०'' अंश — शाब्दिक अर्थ: प्रहार।'),
(140,'हर्षण योग नित्य योगमध्ये १४ औं योग हो। सूर्य र चन्द्रको जोडलाई १७३°२०'' – १८६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ आनन्द र उल्लास भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Harshana Yoga is number 14 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 173°20'' – 186°40''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। हर्षण योगको शाब्दिक अर्थ आनन्द र उल्लास हो। यस योगको डिग्री सीमा १७३°२०'' – १८६°४०'' हो, जुन १४ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','हर्षण योग','सूर्य-चन्द्र जोडको १७३°२०'' – १८६°४०'' अंश — शाब्दिक अर्थ: आनन्द र उल्लास।'),
(141,'वज्र योग नित्य योगमध्ये १५ औं योग हो। सूर्य र चन्द्रको जोडलाई १८६°४०'' – २००°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ वज्र जस्तो बल भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Vajra Yoga is number 15 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 186°40'' – 200°00''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। वज्र योगको शाब्दिक अर्थ वज्र जस्तो बल हो। यस योगको डिग्री सीमा १८६°४०'' – २००°००'' हो, जुन १५ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','वज्र योग','सूर्य-चन्द्र जोडको १८६°४०'' – २००°००'' अंश — शाब्दिक अर्थ: वज्र जस्तो बल।'),
(142,'सिद्धि योग नित्य योगमध्ये १६ औं योग हो। सूर्य र चन्द्रको जोडलाई २००°००'' – २१३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ सिद्धि र सफलता भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Siddhi Yoga is number 16 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 200°00'' – 213°20''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। सिद्धि योगको शाब्दिक अर्थ सिद्धि र सफलता हो। यस योगको डिग्री सीमा २००°००'' – २१३°२०'' हो, जुन १६ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','सिद्धि योग','सूर्य-चन्द्र जोडको २००°००'' – २१३°२०'' अंश — शाब्दिक अर्थ: सिद्धि र सफलता।'),
(143,'व्यतीपात योग नित्य योगमध्ये १७ औं योग हो। सूर्य र चन्द्रको जोडलाई २१३°२०'' – २२६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ आपत् र उथलपुथल भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Vyatipata Yoga is number 17 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 213°20'' – 226°40''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। व्यतीपात योगको शाब्दिक अर्थ आपत् र उथलपुथल हो। यस योगको डिग्री सीमा २१३°२०'' – २२६°४०'' हो, जुन १७ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','व्यतीपात योग','सूर्य-चन्द्र जोडको २१३°२०'' – २२६°४०'' अंश — शाब्दिक अर्थ: आपत् र उथलपुथल।'),
(144,'वरीयान् योग नित्य योगमध्ये १८ औं योग हो। सूर्य र चन्द्रको जोडलाई २२६°४०'' – २४०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ रोकथाम र अवरोध भन्ने यस योगलाई कम अनुकूल योगको रूपमा चिनिन्छ।','Variyana Yoga is number 18 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 226°40'' – 240°00''. Traditional classification: less favourable.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। वरीयान् योगको शाब्दिक अर्थ रोकथाम र अवरोध हो। यस योगको डिग्री सीमा २२६°४०'' – २४०°००'' हो, जुन १८ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो कम अनुकूल योग हो र सामान्य काम गर्न मिल्छ, तर अति महत्त्वपूर्ण मङ्गलिक कामका लागि राम्रो योग हेर्नु उचित हुन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','वरीयान् योग','सूर्य-चन्द्र जोडको २२६°४०'' – २४०°००'' अंश — शाब्दिक अर्थ: रोकथाम र अवरोध।'),
(145,'परिघ योग नित्य योगमध्ये १९ औं योग हो। सूर्य र चन्द्रको जोडलाई २४०°००'' – २५३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ लोहे को ढोका जस्तो अवरोध भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Parigha Yoga is number 19 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 240°00'' – 253°20''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। परिघ योगको शाब्दिक अर्थ लोहे को ढोका जस्तो अवरोध हो। यस योगको डिग्री सीमा २४०°००'' – २५३°२०'' हो, जुन १९ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','परिघ योग','सूर्य-चन्द्र जोडको २४०°००'' – २५३°२०'' अंश — शाब्दिक अर्थ: लोहे को ढोका जस्तो अवरोध।'),
(146,'शिव योग नित्य योगमध्ये २० औं योग हो। सूर्य र चन्द्रको जोडलाई २५३°२०'' – २६६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ कल्याण भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Shiva Yoga is number 20 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 253°20'' – 266°40''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। शिव योगको शाब्दिक अर्थ कल्याण हो। यस योगको डिग्री सीमा २५३°२०'' – २६६°४०'' हो, जुन २० औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','शिव योग','सूर्य-चन्द्र जोडको २५३°२०'' – २६६°४०'' अंश — शाब्दिक अर्थ: कल्याण।'),
(147,'सिद्ध योग नित्य योगमध्ये २१ औं योग हो। सूर्य र चन्द्रको जोडलाई २६६°४०'' – २८०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ सिद्धि प्राप्त भन्ने यस योगलाई अति शुभ योगको रूपमा चिनिन्छ।','Siddha Yoga is number 21 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 266°40'' – 280°00''. Traditional classification: highly auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। सिद्ध योगको शाब्दिक अर्थ सिद्धि प्राप्त हो। यस योगको डिग्री सीमा २६६°४०'' – २८०°००'' हो, जुन २१ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अति शुभ योग हो र यो सबैभन्दा शुभ योगहरू मध्ये एक मानिन्छ — नयाँ उपक्रम, विवाह, गृहप्रवेश र धार्मिक कार्यका लागि विशेष अनुकूल। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','सिद्ध योग','सूर्य-चन्द्र जोडको २६६°४०'' – २८०°००'' अंश — शाब्दिक अर्थ: सिद्धि प्राप्त।'),
(148,'साध्य योग नित्य योगमध्ये २२ औं योग हो। सूर्य र चन्द्रको जोडलाई २८०°००'' – २९३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ साध्य — हुने योग्य भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Sadhya Yoga is number 22 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 280°00'' – 293°20''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। साध्य योगको शाब्दिक अर्थ साध्य — हुने योग्य हो। यस योगको डिग्री सीमा २८०°००'' – २९३°२०'' हो, जुन २२ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','साध्य योग','सूर्य-चन्द्र जोडको २८०°००'' – २९३°२०'' अंश — शाब्दिक अर्थ: साध्य — हुने योग्य।'),
(149,'शुभ योग नित्य योगमध्ये २३ औं योग हो। सूर्य र चन्द्रको जोडलाई २९३°२०'' – ३०६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ शुभ भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Shubha Yoga is number 23 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 293°20'' – 306°40''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। शुभ योगको शाब्दिक अर्थ शुभ हो। यस योगको डिग्री सीमा २९३°२०'' – ३०६°४०'' हो, जुन २३ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','शुभ योग','सूर्य-चन्द्र जोडको २९३°२०'' – ३०६°४०'' अंश — शाब्दिक अर्थ: शुभ।'),
(150,'शुक्ल योग नित्य योगमध्ये २४ औं योग हो। सूर्य र चन्द्रको जोडलाई ३०६°४०'' – ३२०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ शुद्ध र उज्यालो भन्ने यस योगलाई शुभ योगको रूपमा चिनिन्छ।','Shukla Yoga is number 24 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 306°40'' – 320°00''. Traditional classification: auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। शुक्ल योगको शाब्दिक अर्थ शुद्ध र उज्यालो हो। यस योगको डिग्री सीमा ३०६°४०'' – ३२०°००'' हो, जुन २४ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो शुभ योग हो र शुभ र मङ्गलिक कामका लागि अनुकूल मानिन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','शुक्ल योग','सूर्य-चन्द्र जोडको ३०६°४०'' – ३२०°००'' अंश — शाब्दिक अर्थ: शुद्ध र उज्यालो।'),
(151,'ब्रह्म योग नित्य योगमध्ये २५ औं योग हो। सूर्य र चन्द्रको जोडलाई ३२०°००'' – ३३३°२०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ ब्रह्मा भन्ने यस योगलाई अति शुभ योगको रूपमा चिनिन्छ।','Brahma Yoga is number 25 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 320°00'' – 333°20''. Traditional classification: highly auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। ब्रह्म योगको शाब्दिक अर्थ ब्रह्मा हो। यस योगको डिग्री सीमा ३२०°००'' – ३३३°२०'' हो, जुन २५ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अति शुभ योग हो र यो सबैभन्दा शुभ योगहरू मध्ये एक मानिन्छ — नयाँ उपक्रम, विवाह, गृहप्रवेश र धार्मिक कार्यका लागि विशेष अनुकूल। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','ब्रह्म योग','सूर्य-चन्द्र जोडको ३२०°००'' – ३३३°२०'' अंश — शाब्दिक अर्थ: ब्रह्मा।'),
(152,'इन्द्र योग नित्य योगमध्ये २६ औं योग हो। सूर्य र चन्द्रको जोडलाई ३३३°२०'' – ३४६°४०'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ इन्द्र भन्ने यस योगलाई अति शुभ योगको रूपमा चिनिन्छ।','Indra Yoga is number 26 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 333°20'' – 346°40''. Traditional classification: highly auspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। इन्द्र योगको शाब्दिक अर्थ इन्द्र हो। यस योगको डिग्री सीमा ३३३°२०'' – ३४६°४०'' हो, जुन २६ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अति शुभ योग हो र यो सबैभन्दा शुभ योगहरू मध्ये एक मानिन्छ — नयाँ उपक्रम, विवाह, गृहप्रवेश र धार्मिक कार्यका लागि विशेष अनुकूल। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','इन्द्र योग','सूर्य-चन्द्र जोडको ३३३°२०'' – ३४६°४०'' अंश — शाब्दिक अर्थ: इन्द्र।'),
(153,'वैधृति योग नित्य योगमध्ये २७ औं योग हो। सूर्य र चन्द्रको जोडलाई ३४६°४०'' – ३६०°००'' को बीच भएको बेला यो योग मानिन्छ। शब्दार्थ विच्छेद र अस्थिरता भन्ने यस योगलाई अशुभ योगको रूपमा चिनिन्छ।','Vaidhriti Yoga is number 27 of the 27 nitya yogas. It applies when the combined Sun–Moon longitude falls between 346°40'' – 360°00''. Traditional classification: inauspicious.','नित्य योग भनेको सूर्य र चन्द्रको जोडलाई १३°२० ले भाग गरेर निकालिने २७ वटा योगहरूमध्ये एक हो — यसरी एक चन्द्र मासमा एकपछि अर्को २७ नै योगहरू आउँछन्। वैधृति योगको शाब्दिक अर्थ विच्छेद र अस्थिरता हो। यस योगको डिग्री सीमा ३४६°४०'' – ३६०°००'' हो, जुन २७ औं योगको पर्याय हो। यसले दिएको विचार दैनिक र जन्मगत दुवै कुरामा हेरिन्छ।','परम्परागत विचारअनुसार यो अशुभ योग हो र शुभ कामका लागि अनुकूल मानिँदैन र यस दिन मङ्गलिक काम र सुरुवात टाढा राख्ने सल्लाह दिइन्छ। दैनिक पञ्चाङ्गमा हेरेर शुभ कामको समय रोज्ने बेलामा यो योगको हिसाब गरिन्छ।','ज्योतिष शास्त्र — नित्य योग (३६०° ÷ २७ = १३°२० प्रति योग)','वैधृति योग','सूर्य-चन्द्र जोडको ३४६°४०'' – ३६०°००'' अंश — शाब्दिक अर्थ: विच्छेद र अस्थिरता।'),
(154,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। बव करण चर करण हो र यो एक चन्द्र मासमा ८ पटक आउँछ — चर करणहरू कुल ५६ पटक देखिन्छन्। यसलाई चर (पुनरावृत्ति हुने) करणहरूको सूचीमा राखिन्छ।','Bava Karana is half a tithi. It is a Chara karana — the seven chara karanas recur eight times in a lunar month, covering 56 of the 60 karanas. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। करण भनेको तिथिको आधा हो: एक तिथि = २ करण, मासमा ३० तिथि = ६० करण। बव करणमा आएका काम सुरु गर्दा काम सजिलै बढ्ने र शान्तिपूर्ण ढंगले पूरा हुने मानिन्छ।','साधारण रूपमा शुभ मानिन्छ — यात्रा, व्यापार र शुभ संकल्पका काममा अनुकूल। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','बव करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(155,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। बालव करण चर करण हो र यो एक चन्द्र मासमा ८ पटक आउँछ। यसलाई चर (पुनरावृत्ति हुने) करणहरूको सूचीमा राखिन्छ।','Balava Karana is half a tithi. It is a Chara karana — the seven chara karanas recur eight times in a lunar month, covering 56 of the 60 karanas. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। बालव करणलाई बालरूपी शक्ति दिने मानिन्छ। परिवार र सन्तानसम्बन्धी काम, नयाँ काम र सामाजिक आयोजनमा यो करण हेरिन्छ।','सामान्यतया शुभ, तर आरोग्य र शारीरिक काममा थोरै सावधानीको सल्लाह दिइन्छ। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','बालव करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(156,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। कौलव करण चर करण हो र यो एक चन्द्र मासमा ८ पटक आउँछ। यसलाई चर (पुनरावृत्ति हुने) करणहरूको सूचीमा राखिन्छ।','Kaulava Karana is half a tithi. It is a Chara karana — the seven chara karanas recur eight times in a lunar month, covering 56 of the 60 karanas. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। कुल (परिवार) सँग जोडिएको करण मानिन्छ — परिवारका काम, वंशसम्बन्धी आयोजन र सम्बन्ध विस्तारका काममा हेरिन्छ।','शुभ मानिन्छ; पारिवारिक र सामाजिक काममा अनुकूल। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','कौलव करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(157,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। तैतिल करण चर करण हो र यो एक चन्द्र मासमा ८ पटक आउँछ। यसलाई चर (पुनरावृत्ति हुने) करणहरूको सूचीमा राखिन्छ।','Taitila Karana is half a tithi. It is a Chara karana — the seven chara karanas recur eight times in a lunar month, covering 56 of the 60 karanas. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। तैतिल करणलाई तेल र स्निग्धतासँग जोडेर हेरिन्छ — स्नान, तेल लगाउने, औषधि र शारीरिक स्वास्थ्यसम्बन्धी काममा विशेष।','शुभ मानिन्छ; स्वास्थ्य, स्नान र औषधिसम्बन्धी काममा अनुकूल। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','तैतिल करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(158,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। गर करण चर करण हो र यो एक चन्द्र मासमा ८ पटक आउँछ। यसलाई चर (पुनरावृत्ति हुने) करणहरूको सूचीमा राखिन्छ।','Garaja Karana is half a tithi. It is a Chara karana — the seven chara karanas recur eight times in a lunar month, covering 56 of the 60 karanas. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। गर करणले भूमि, गर र निर्माणसँग सम्बन्धित कामलाई जनाउँछ — भूमि किन्ने, घर बनाउने र कृषिसम्बन्धी काममा हेरिन्छ।','सामान्यतया शुभ, तर भूमि-सम्बन्धी विवादमा सतर्कता उचित। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','गर करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(159,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। वणिज करण चर करण हो र यो एक चन्द्र मासमा ८ पटक आउँछ। यसलाई चर (पुनरावृत्ति हुने) करणहरूको सूचीमा राखिन्छ।','Vanija Karana is half a tithi. It is a Chara karana — the seven chara karanas recur eight times in a lunar month, covering 56 of the 60 karanas. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। वणिज भनेको व्यापारी — यो करण व्यापार, क्रय-विक्रय, सौदा र लेनदेनका काममा विशेष रूपमा हेरिन्छ।','व्यापार र आर्थिक कामका लागि शुभ मानिन्छ। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','वणिज करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(160,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। विष्टि करण चर करण हो र यो एक चन्द्र मासमा ८ पटक आउँछ; यसलाई भद्रा पनि भनिन्छ। यसलाई चर (पुनरावृत्ति हुने) करणहरूको सूचीमा राखिन्छ।','Vishti Karana is half a tithi. It is a Chara karana — the seven chara karanas recur eight times in a lunar month, covering 56 of the 60 karanas. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। विष्टि (भद्रा) करणलाई बाधा र विलम्ब दिने करण मानिन्छ। प्राचीन परम्परामा यो करणमा शुभ कामको समय रोज्ने बेलामा विशेष ध्यान दिइन्छ।','अशुभ मानिन्छ — विवाह, गृहप्रवेश र नयाँ उपक्रम जस्ता मङ्गलिक काम यस करणमा टाढा राख्ने चलन छ। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','विष्टि करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(161,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। शकुनि करण स्थिर करण हो र यो चन्द्र मासमा एकैपटक — कृष्ण पक्षको चतुर्दशी तिथिको दोस्रो भागमा मात्र आउँछ। यसलाई स्थिर (मासमा एकैपटक आउने) करणहरूको सूचीमा राखिन्छ।','Shakuni Karana is half a tithi. It is a Fixed karana — the fixed karanas occur only once in a lunar month. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। शकुनि भनेको शकुन-अपशकुन पढ्ने वा बिदुको विशेषज्ञ — यो स्थिर करणहरूमध्ये एक हो, जुन मासमा एकैपटक देखिन्छ। कृष्ण चतुर्दशीको दोस्रो भागमा पर्ने यो करण रणनीति र विश्लेषणसँग जोडिएको मानिन्छ।','अशुभ मानिन्छ — शुभ कामका लागि उपयुक्त मानिँदैन। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','शकुनि करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(162,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। चतुष्पाद करण स्थिर करण हो र यो चन्द्र मासमा एकैपटक — अमावस्या तिथिको पहिलो भागमा मात्र आउँछ। यसलाई स्थिर (मासमा एकैपटक आउने) करणहरूको सूचीमा राखिन्छ।','Chatushpada Karana is half a tithi. It is a Fixed karana — the fixed karanas occur only once in a lunar month. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। चतुष्पाद भनेको चार पाइँ भएको — पशु र पशुपालनसँग सम्बन्धित करण। यो अमावस्याको पहिलो भागमा पर्ने स्थिर करण हो र पितृकार्य, तर्पण र पशुसम्बन्धी काममा हेरिन्छ।','अमावस्यासँग जोडिएकाले शुभ काममा उपयुक्त मानिँदैन; पितृ तर्पण जस्ता कार्यमा महत्त्वपूर्ण। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','चतुष्पाद करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(163,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। नाग करण स्थिर करण हो र यो चन्द्र मासमा एकैपटक — अमावस्या तिथिको दोस्रो भागमा मात्र आउँछ। यसलाई स्थिर (मासमा एकैपटक आउने) करणहरूको सूचीमा राखिन्छ।','Naga Karana is half a tithi. It is a Fixed karana — the fixed karanas occur only once in a lunar month. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। नाग करण नागदेवतासँग जोडिएको छ — खनिज, सर्प, गहना र भूमिगत सम्पदासँग सम्बन्धित मानिन्छ। यो पनि अमावस्याको दोस्रो भागमा पर्ने स्थिर करण हो।','अमावस्यासँग जोडिएकाले सामान्य शुभ काममा उपयुक्त मानिँदैन; नागपूजा र सम्बन्धी अनुष्ठानमा महत्त्वपूर्ण। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','नाग करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(164,'करण भनेको एक तिथिको आधा भाग हो — मासमा ६० करण आउँछन्। किंस्तुघ्न करण स्थिर करण हो र यो चन्द्र मासमा एकैपटक — शुक्ल पक्षको प्रतिपदा तिथिको पहिलो भागमा मात्र आउँछ। यसलाई स्थिर (मासमा एकैपटक आउने) करणहरूको सूचीमा राखिन्छ।','Kimstughna Karana is half a tithi. It is a Fixed karana — the fixed karanas occur only once in a lunar month. Its traditional significance is tied to the actions described below.','चन्द्र मासमा ३० तिथि हुन्छन्, र प्रत्येक तिथिका दुई भाग हुने भएकाले कुल ६० करण आउँछन्। यी ६० मध्ये ७ चर करणहरू ८-८ पटक देखिन्छन् (५६), र ४ स्थिर करणहरू मासमा एक-एक पटक (४) — यसरी ११ करण पूरा हुन्छन्। किंस्तुघ्नले क्षय गर्ने शक्ति जनाउँछ — चन्द्रमा सूर्यबाट टाढा बढ्ने बेलाको पहिलो खण्डमा पर्ने यो करण नयाँ चक्रको सुरुवात सँगै आउँछ।','नयाँ आरम्भ र नाशात्मक काममा विशेष महत्त्व दिइन्छ; सामान्य मङ्गलिक काममा विशेष शुभ मानिँदैन। पञ्चाङ्गमा दैनिक काम रोज्दा तिथिको साथै करण पनि हेरिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग करण (आधा तिथि)','किंस्तुघ्न करण','तिथिको आधा भाग — मासमा ६० करण, मध्ये ११ नामवाला।'),
(165,'पञ्चाङ्ग भनेको हिन्दू र वैदिक परम्पराको ज्योतिषीय पात्रो प्रणाली हो, जसले समयलाई पाँच आधारमा मापन गर्छ। संस्कृतमा पञ्चाङ्ग शब्द "पाँच अंग" भन्ने अर्थ राख्छ र यसमा तिथि, वार, नक्षत्र, योग र करण — यी पाँचवटा तत्त्व पर्छन्।','What is Panchanga? The panchanga measures time through five limbs — tithi, vara, nakshatra, yoga and karana — and is used to decide auspicious days and moments.','पञ्चाङ्गले आजको दिनको गुण, शुभाशुभ र समयलाई बताउँछ। जसरी इंग्रेजी क्यालेन्डरले सूर्यमा आधारित महिना मापन गर्छ, त्यसरी नै पञ्चाङ्गले चन्द्र र सूर्यबीचको सम्बन्धमा आधारित दिन र तिथि मापन गर्छ। नेपालमा विवाह, गृहप्रवेश, यात्रा, व्रत र पर्वहरूको मिति तोक्न पञ्चाङ्गकै प्रयोग हुन्छ।','पञ्चाङ्गमा दिनको समय सूर्योदयबाट मापन गरिन्छ र हरेक तिथि, नक्षत्र वा योग सूर्योदयमा कुन अवस्थामा छ भनेर त्यसको नाम र फल बुझिन्छ। पञ्चाङ्ग पढ्नका लागि सूर्य र चन्द्रको डिग्री, स्थानीय समय र ज्योतिषीय गणना आवश्यक पर्छ।','वैदिक ज्योतिष — पञ्चाङ्ग परिचय','पञ्चाङ्ग के हो?','पञ्चाङ्ग (पाँच अंग) — तिथि, वार, नक्षत्र, योग र करणमा आधारित वैदिक पात्रो प्रणाली।'),
(166,'पञ्चाङ्गका पाँच अंग हुन् — तिथि (सूर्य-चन्द्र दूरीको १२ डिग्री खण्ड), वार (हप्ताको एक दिन, ग्रहस्ँग जोडिएको), नक्षत्र (चन्द्रको २७ नक्षत्र), योग (सूर्य-चन्द्र जोडको २७ भाग) र करण (तिथिको आधा, ११ नामका करण)।','The Five Limbs of Panchanga The panchanga measures time through five limbs — tithi, vara, nakshatra, yoga and karana — and is used to decide auspicious days and moments.','यी पाँच अंगहरू एकअर्कासँग मिलेर दिनको पञ्चाङ्ग बनाउँछन्। तिथिले चन्द्रमाको बढ्दो-घट्दो अवस्था देखाउँछ, वारले ग्रहको दैनिक स्वामित्व, नक्षत्रले चन्द्रको चालसँग जोडिएका ऋषि-देवताको विचार, योगले दैनिक समग्र गुण र करणले काम गर्ने आधा तिथिको अवस्था बताउँछ।','जन्म कुण्डली पढ्दा पनि यी पाँचै अंगहरू हेरिन्छन् — जन्मनाम निर्धारण, नक्षत्र-गुण, दशाफल र शुभ मुहूर्त तोक्दा पञ्चाङ्गको महत्त्व देखिन्छ। नेपाली परम्परामा बिहे-वर्ष, ब्रतबन्ध र घर बसाइँ जस्ता काममा पञ्चाङ्गका आधारमा शुभ दिन र समय रोजिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग परिचय','पञ्चाङ्गका पाँच अंग','पञ्चाङ्ग (पाँच अंग) — तिथि, वार, नक्षत्र, योग र करणमा आधारित वैदिक पात्रो प्रणाली।'),
(167,'पञ्चाङ्ग प्रणालीमा एक वर्षलाई संवत्सर भनिन्छ। चन्द्र मास र सौर वर्ष मिलाउन — लगभग ३५४ दिनको चन्द्र वर्ष र ३६५ दिनको सौर वर्ष बीचको भिन्नता मिटाउन १९ वर्षमा एकपटक अधिक मास (मलमास) जोडिन्छ।','Samvat and the Year The panchanga measures time through five limbs — tithi, vara, nakshatra, yoga and karana — and is used to decide auspicious days and moments.','नेपाल र भारतमा विभिन्न संवत्सर प्रचलित छन् — विक्रम संवत्सर र नेपाल सम्वत् प्रमुख छन्। विक्रम संवत्सरको अभियान ५७ ई. देखि सुरु मानिन्छ भने नेपाल सम्वत् प्राचीन लिच्छवि कालदेखि चलिआएको छ। यसरी नयाँ संवत्सरको पहिलो दिन चैत्र र वैशाख महिनामा मानिन्छ।','संवत्सरको नाम राशि, ग्रह वा नक्षत्रमा आधारित हुन्छ र यसले त्यस वर्षको समग्र वातावरण जनाउने मान्यता छ। पात्रो गणनामा मलमास, क्षय तिथि र सूर्य-चन्द्रको स्थिति जोडेर नै वर्षको लम्बाइ तोकिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग परिचय','संवत्सर र वर्ष','पञ्चाङ्ग (पाँच अंग) — तिथि, वार, नक्षत्र, योग र करणमा आधारित वैदिक पात्रो प्रणाली।'),
(168,'चन्द्र मासलाई शुक्ल र कृष्ण — दुई पक्षमा विभाजन गरिन्छ, जसमा १५-१५ तिथि हुन्छन्। ऋतु (वसन्त, ग्रीष्म, वर्षा, शरद, हेमन्त, शिशिर) ले सौर वर्षको छ भाग बनाउँछन्, जुन कृषि र पर्वसँग गहिरो रूपमा जोडिएको छ।','Seasons and Months The panchanga measures time through five limbs — tithi, vara, nakshatra, yoga and karana — and is used to decide auspicious days and moments.','प्रत्येक ऋतु लगभग दुई महिनाको हुन्छ र सूर्यको राशि परिवर्तन (संक्रान्ति) सँगै ऋतु बदलिन्छ। वैशाख-जेठ ग्रीष्म, असार-भदौ वर्षा, चैत-बैशाख वसन्त जस्तो नेपाली परम्परा अनुसारको विभाजन पनि चलनमा छ। तिहार, दशैँ, छठ जस्ता पर्व ऋतु र पात्रोसँग मिलेर नै मनाइन्छ।','मासको नाम पूर्णिमा वा अमावस्यामा पुगेको नक्षत्रमा आधारित हुन्छ — जस्तै भाद्र, अश्विन, कात्तिक। यसरी नक्षत्र, ऋतु र मास मिलेर कृषि चक्र र सामाजिक कार्यलयलाई संचालन गर्छन्।','वैदिक ज्योतिष — पञ्चाङ्ग परिचय','ऋतु र मास','पञ्चाङ्ग (पाँच अंग) — तिथि, वार, नक्षत्र, योग र करणमा आधारित वैदिक पात्रो प्रणाली।'),
(169,'मुहूर्त भनेको कुनै काम सुरु गर्नका लागि हेरिने शुभ समय हो। यसमा तिथि, वार, नक्षत्र, योग, करण, लग्न र ग्रहसँग जोडिएका शुभाशुभ अवस्था हेरेर दिन र समय तोकिन्छ।','Introduction to Muhurta The panchanga measures time through five limbs — tithi, vara, nakshatra, yoga and karana — and is used to decide auspicious days and moments.','मुहूर्त विचार्दा अभिजित्, विजय मुहूर्त, रवि-सोम योग, अमृत योग जस्ता शुभ काल हेरिन्छ भने राहु काल, गुलिक काल, यमगण्ड जस्ता अशुभ काल टाढा राखिन्छ। विवाहका लागि अभिजित् लग्न, यात्राका लागि विजय मुहूर्त, गृहप्रवेशका लागि तिथि-वार-नक्षत्र अनुकूल हुनुपर्ने गरी नियम बनेका छन्।','मुहूर्त तोक्दा स्थानीय सूर्योदय, लग्न, चन्द्रको स्थिति र त्यस दिनको पञ्चाङ्ग मिलाउनुपर्छ। आजका पञ्चाङ्ग पात्रा र एपहरूले यो गणना सजिलो बनाइदिए पनि, महत्त्वपूर्ण काममा अनुभवी ज्योतिषीसँग परामर्श गर्नु उचित मानिन्छ।','वैदिक ज्योतिष — पञ्चाङ्ग परिचय','शुभ मुहूर्तको परिचय','पञ्चाङ्ग (पाँच अंग) — तिथि, वार, नक्षत्र, योग र करणमा आधारित वैदिक पात्रो प्रणाली।');
